<style>
  body {
    background-color: #f2f2f2;
    display: flex;
    justify-content: center;
    font-family: "Microsoft YaHei", "SimHei", sans-serif;
    margin: 0;
    padding: 20px 0;
  }

  .page {
    position: relative;
    width: 560px;
    min-height: 700px;
    background-color: #ffffff;
    box-sizing: border-box;
    padding: 40px 45px;
  }

  /* corner brackets */
  .corner {
    position: absolute;
    width: 30px;
    height: 30px;
    border: 3px solid #a9c1af;
  }
  .corner.top-left {
    top: 12px;
    left: 12px;
    border-right: none;
    border-bottom: none;
  }
  .corner.top-right {
    top: 12px;
    right: 12px;
    border-left: none;
    border-bottom: none;
  }
  .corner.bottom-left {
    bottom: 12px;
    left: 12px;
    border-right: none;
    border-top: none;
  }
  .corner.bottom-right {
    bottom: 12px;
    right: 12px;
    border-left: none;
    border-top: none;
  }

  h1.title {
    text-align: center;
    font-size: 26px;
    font-weight: bold;
    letter-spacing: 2px;
    margin: 15px 0 30px 0;
    color: #1a1a1a;
  }

  p.intro {
    font-size: 15px;
    line-height: 2;
    color: #1a1a1a;
    margin: 0 0 30px 0;
    text-align: justify;
  }

  .highlight {
    color: #e04b3f;
    font-weight: bold;
  }

  h2.section {
    font-size: 16px;
    font-weight: bold;
    margin: 25px 0 12px 0;
    color: #1a1a1a;
  }

  p.section-text {
    font-size: 15px;
    line-height: 2;
    color: #1a1a1a;
    margin: 0 0 10px 0;
    text-align: justify;
  }

  .flip-btn {
    position: absolute;
    right: 45px;
    bottom: 90px;
    background-color: #1a1a1a;
    color: #ffffff;
    font-size: 13px;
    padding: 8px 20px;
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .footer {
    position: absolute;
    bottom: 30px;
    left: 0;
    right: 0;
    text-align: center;
    font-size: 13px;
    color: #333333;
  }
</style>
